import gurobipy as gp
from gurobipy import GRB
workstation_records = [rec for rec in LEGACY_RECORDS if rec.get('values', {}).get('Workstation') in {'1', '2', '3'}]
model_names = []
for key in workstation_records[0]['values']:
    if key.startswith('HiFi') and key.endswith('_Minutes'):
        model_names.append(key)
model_names.sort(key=lambda x: int(x.replace('HiFi', '').replace('_Minutes', '')))
if len(model_names) != 101:
    raise ValueError('Expected 101 models, got %d' % len(model_names))
workstation_names = [rec['values']['Workstation'] for rec in workstation_records]
if workstation_names != ['1', '2', '3']:
    raise ValueError('Expected workstations 1,2,3')
t = {}
for widx, rec in enumerate(workstation_records):
    w = workstation_names[widx]
    t[w] = {}
    for k in model_names:
        t[w][k] = int(rec['values'][k])
maintenance_percent = {}
C = {}
for widx, rec in enumerate(workstation_records):
    w = workstation_names[widx]
    maintenance_percent[w] = float(rec['values']['Maintenance_Percent']) / 100.0
    C[w] = 1440 * (1 - maintenance_percent[w])
for w in workstation_names:
    for k in model_names:
        if k not in t[w]:
            raise ValueError(f'Missing processing time for workstation {w}, model {k}')
m = gp.Model('Radio_IdleTime_Min')
x = m.addVars(model_names, lb=0, vtype=GRB.INTEGER, name='')
for w in workstation_names:
    m.addConstr(gp.quicksum((t[w][k] * x[k] for k in model_names)) <= C[w], name=f'cap_{w}')
idle_time_expr = gp.quicksum((C[w] - gp.quicksum((t[w][k] * x[k] for k in model_names)) for w in workstation_names))
m.setObjective(idle_time_expr, GRB.MINIMIZE)
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')